import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import '../../../core/providers/app_providers.dart';import '../../../core/domain/care_entities.dart';
class RecordEditorScreen extends ConsumerStatefulWidget{const RecordEditorScreen({super.key});@override ConsumerState<RecordEditorScreen> createState()=>_RecordEditorScreenState();}
class _RecordEditorScreenState extends ConsumerState<RecordEditorScreen>{final title=TextEditingController(),clinic=TextEditingController(),notes=TextEditingController(),follow=TextEditingController();String type='Vaccination';@override void dispose(){title.dispose();clinic.dispose();notes.dispose();follow.dispose();super.dispose();}
Future<void> save()async{final p=ref.read(appControllerProvider).selectedPet;if(p==null||title.text.trim().isEmpty)return;final e=PetRecord(id:DateTime.now().microsecondsSinceEpoch.toString(),petId:p.id,type:type,title:title.text.trim(),eventDate:DateTime.now(),followUpDate:DateTime.tryParse(follow.text),clinic:clinic.text.trim(),notes:notes.text.trim());await ref.read(appControllerProvider).save('pet_records',e.toMap());if(mounted)Navigator.pop(context);}
@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Add health record')),body:ListView(padding:const EdgeInsets.all(20),children:[DropdownButtonFormField<String>(value:type,decoration:const InputDecoration(labelText:'Record type'),items:['Vaccination','Vet visit','Preventive care','Other'].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>setState(()=>type=v!)),const SizedBox(height:12),TextField(controller:title,decoration:const InputDecoration(labelText:'Record title / vaccine name *')),const SizedBox(height:12),TextField(controller:clinic,decoration:const InputDecoration(labelText:'Clinic (optional)')),const SizedBox(height:12),TextField(controller:follow,decoration:const InputDecoration(labelText:'Vet-supplied follow-up date (YYYY-MM-DD)')),const SizedBox(height:12),TextField(controller:notes,maxLines:4,decoration:const InputDecoration(labelText:'Owner-entered notes')),const SizedBox(height:10),const Text('Entered by you · PawPal does not verify records or recommend medical schedules.'),const SizedBox(height:20),FilledButton(onPressed:save,child:const Text('Save record'))]));}
